slides.solution:
import ast
import operator

OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}

def safe_calc(expr: str) -> float:
    return _walk(ast.parse(expr, mode="eval"))

def _walk(node):
    if isinstance(node, ast.Expression):
        return _walk(node.body)
    if isinstance(node, ast.Constant) and type(node.value) in (int, float):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in OPS:
        return OPS[type(node.op)](_walk(node.left), _walk(node.right))
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        return -_walk(node.operand)
    raise ValueError(f"not allowed: {type(node).__name__}")

print(safe_calc("2 + 3 * 4"))

slides.tests:
assert safe_calc("2 + 3 * 4") == 14, "safe_calc('2 + 3 * 4') should be 14."
assert safe_calc("(10 - 4) / 3") == 2.0, "safe_calc('(10 - 4) / 3') should be 2.0."
assert safe_calc("-5 + 2") == -3, "Support unary minus: safe_calc('-5 + 2') should be -3."
for evil in ["__import__('os').getcwd()", "open('secrets.txt').read()", "2 ** 100000000", "price * 2"]:
    try:
        result = safe_calc(evil)
    except ValueError:
        continue
    raise AssertionError("safe_calc(" + repr(evil) + ") was evaluated instead of raising ValueError. Use the ast allow-list, not eval.")
